# Auto-fetch custom_sales_person, custom_technician & custom_technician_name on Sales Order Save
for item in doc.get("items", []):
    if item.get("quotation_item"):
        q_item = frappe.db.get_value("Quotation Item", item.quotation_item, ["custom_sales_person", "custom_technician", "custom_technician_name"], as_dict=True)
        if q_item:
            if not item.get("custom_sales_person") and q_item.get("custom_sales_person"):
                item.custom_sales_person = q_item.custom_sales_person
            if not item.get("custom_technician") and q_item.get("custom_technician"):
                item.custom_technician = q_item.custom_technician
            if not item.get("custom_technician_name") and q_item.get("custom_technician_name"):
                item.custom_technician_name = q_item.custom_technician_name

    if item.get("custom_technician") and not item.get("custom_technician_name"):
        emp_name = frappe.db.get_value("Employee", item.custom_technician, "employee_name")
        if emp_name:
            item.custom_technician_name = emp_name
